      "মা-বোনর ইজ্জদ্ ললে,",
      "ডদ্দর....! থত্তর... !",
      "ঘুরি ন' পাত্তন্ ঝাড়ে-জঙলে।",
      "__STANZA__",
      "তুই অমানুচ্! তুই রেক্কস্!",
      "তর ইনছাপ্ নেই।",
      "মরে কছ্ খাপ্পো!",
