      "যেন্, পাজন্ তোনোত্,",
      "শুগুনো মাছ্।",
      "ঘরে ঘরে বিঝু চলের,",
      "সুদিন্ বারমাস্।",
      "__STANZA__",
      "রম'চক্র ভেদ্ ধুরি!",
      "কধা চলে দাত্ ভিরি!",
      "মুরে মুরে আইপাই।",
      "গাচ্ছো কাবিবে কুড়োলে ;কুড়োলে নে'নাহ্ আগারে?",
      "জাদ' মাধা জাদে খার।",
      "__STANZA__",
      "ইক্কো কয়দি এদুংনাহি?",
      "ইক্কো কয়দি থোক্।",
      "গ' গ' নিত্য সাঙুদোর্!",
      "রাণীমিলের ইক্কো পুয়া,",
