      "ন' পারঙ্ আঙিভুঙী,",
      "ভাচ্ মর কানানা,",
      "ফেলানা চোঘোপানি।।।",
      "অবুঝ্ মর কোচপানা,",
      "ন' ভাবীচ্ ছলনা,",
      "অংনাহ্ বেদমা।",
      "এ কোচপানাত্ তরে,",
      "ভাজেই পারিম্,",
      "এ বুগোত্ রাগেই পারিম্,",
      "গদা জীংকানি।।।",
      "__STANZA__",
      "মনানত্ *সায়র জবে,",
      "থদেভদেও জোব্ ন' ছারে।",
      "মনে ন' গুরিচ্ কধা নেই,",
      "যিয়েগোই বেক্ ফুরেই।",
      "ন' আদের কধা বুগোত্,",
      "রংচং স্ববন্ দ্বি চোগোত্।",
      "ভাবী লোচ্ এক্ বুক্ আঝা,",
      "ভুদভুদাই বানাহ্ মুরে মুরে,",
      "র'ধঅ মিলি ন' পারে।।।",
      "__STANZA__",
      "রুবে দোল্,",
      "গুনে **পাংঘা!",
      "কধা বাত্যায় চলনে বলনে।",
      "বেক্কানিত্ ***তুজিমপুরো,",
      "সে যুগোত্ চান্দবী,",
      "ধনপুদি।",
      "অফিত্তি জনম্ কালা!",
      "বিধাতার লিখন্,",
