      "মাঘী আঞ্যেঁ কবালত্ কি গুরিম্,",
      "এ যুগোত্ মুই মনপুদি।",
      "__STANZA__",
      "মনর এ কোচপানা যুনি দেঘি থাচ্,",
      "তুলি লবে আধে ধুরি,",
      "তুই বাদে মুই আকুল্ গুরি...উজু উজু ভাঙীঁচুরি,",
      "বেক্ কোলুঙ্ মুই,",
