    "content": [
      "ষোলো *বেইয়া ফুলর হাদি বুনি ;",
      "সজমজ্ গুরি বুগোত্ বানী।",
      "আঝং আঝং মূ নুদিবানী।",
      "হেলাঙ্ হিলিঙ্ এ মুড়োমুড়িত্ ;",
      "যেন্ শাওন্ ভাধ' মাস্যা,",
      "জ্বলের বেবে বুগোত্ রানজুনি!!!",
      "__STANZA__",
      "বৈজাখ্যা চোখ্ চোখ্ দেবাকালা ;",
      "লাম্বা তার যেন্ চুলানি,",
      "দ্বি তিন্ বের দিনেইও আলাঝালা।",
      "চুলসুধো তাকঠিগিনীত্ ;",
      "বুইয়ারে উড়ের কানজাবা চুল্ ;",
      "চেমনি ন' চেম্??",
      "চেবারও মনে হয়,",
      "দ্বি চোখ্ মর ঝালাপালা!!!",
      "__STANZA__",
      "কালা পিনোন্ রাঙাঁ হাদি ;",
      "নয় অজল্ নয়ও বাদি।",
      "রাঙাঁচাঙাঁ পরানবী মর,",
      "ফিরেপাগে রিনি চেলুঙ্,",
      "চোঘো লেজে মুরে মুরে।।।",
      "স্বর্গর বেক্ সুখ্ এব' ;",
      "নরগর বেক্ দুখকোনি ধেব',",
      "আঝি আঝি পরানবী.......যুনি বোই থাচ্ মর কায়কুরে!!!",
      "~~~~~~~~~~~~~~~~~",
      "__STANZA__",
      "০১/০৬/২০১৫",
      "__STANZA__",
      "( ১১০)কবিতা",
      "__STANZA__",
      "# হিংসা পিঝুম্ #",
      "__STANZA__",
      "গরর দ' গরর গম্ কাম্ ;",
      "দ্বি এক্ জনে পাদন্ ত' নাঙ্।",
      "আর' কিজু মানুচ্ থান্ ;",
      "সে গমান্ গম্ ন' পাহন্।",
      "দুবো আন্দলে কো ধরন্ ;",
      "নয় নয় নয়.............!!!",
      "নিজে দ' কিজু ন' পারন্ ;",
      "মাঞ্যেঁ গল্লে হিংসে গরন্।",
      "জাগি উধে রেচ্য পিড়ে ;",
      "বান্ সজ্ অয় গিরায় গিরে।",
      "লাজ্-দর্ ভুদি বানি ;",
      "উত্তর-দোগিন্ ন' চিনি।",
      "যুনি নিজর স্বাত্ত থায়,",
      "সেক্কে তে পুরোন অয়-লবয়।।।",
      "~~~~~~~`````~~~~~"
    ]
