    "badge": "ছড়া",
    "excerpt": "লুক্কি চিজিক চুক্কি থেচ্,",
    "date": "<w:tab w:val=\"left\" w:pos=\"3402\"/></w:tabs><w:ind w:left=\"0\" w:firstLine=\"0\"/><w:jc w:val=\"center\"/><w:rPr><w:rFonts w:ascii=\"NikoshBAN\" w:hAnsi=\"NikoshBAN\" w:cs=\"NikoshBAN\"/><w:bCs/><w:i/><w:sz w:val=\"24\"/><w:szCs w:val=\"24\"/><w:cs/><w:lang w:bidi=\"bn-IN\"/></w:rPr></w:pPr><w:r w:rsidRPr=\"005D0DDD\"><w:rPr><w:rFonts w:ascii=\"NikoshBAN\" w:hAnsi=\"NikoshBAN\" w:cs=\"NikoshBAN\"/><w:bCs/><w:i/><w:sz w:val=\"24\"/><w:szCs w:val=\"24\"/><w:cs/><w:lang w:bidi=\"bn-IN\"/></w:rPr><w:t>১০/০৯/২০১৫",
    "readTime": "2 মিনিট পাঠ",
    "isFeatured": false,
    "content": [
      "লুক্কি চিজিক চুক্কি থেচ্,",
      "হুজি চিজিক্করে তুই ধোলেচ।",
      "ত' বাবে যিয়ে হাট্টোনত,",
      "জুমান আগে আদ্দানত্।",
      "বিনি ধানান মুজিযার,",
      "চগদা,",
      "বান্দরর,",
      "পেক আধার।",
      "__STANZA__",
      "পুল্যাঙ পুড়েলে মুই ফিরিম,",
      "বিনিহোগা পিধে বানেই দিম্।",
      "মালাহ্ শুগোরবো হাবিলে,",
      "পিধে হেবার তেল পেলে......চাগা চাগা নারিহুল হুদি,",
      "মারেপিধে,",
      "বেঙপিধে দিম্মোই ডুগি।",
      "---- চিজি ঘরত থাক ব'জোচ।",
      "====================="
    ]
