      "বেলান ডুবেল্লোই আঝি আঝি,",
      "বান্দরে শুগাদন ধান।",
      "__STANZA__",
      "মামাহ্ দেল্লোই তোনো তাবা,",
      "নানু ভাঙেরঁ হাঙাড়াঁ।",
      "ফোবে ফোবো চিজি এল'ধাভা উড়িঙ চঙঁরা।",
